INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-047-18', 'p0103', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二年，西征黃祖，虜其人民而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-047-19', 'p0103', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十三年春，權復征黃祖，祖先遣舟兵拒軍，都尉呂蒙破其前鋒，而淩統、董襲等盡銳攻之，遂屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-049-20', 'p0103', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '江表傳曰：策初遣慈，議者紛紜，謂慈未可信，或云與華子魚州里，恐留彼為籌策，或疑慈西託黃祖，假路還北，多言遣之非計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-050-21', 'p0103', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '後從討黃祖，中流矢卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-051-22', 'p0103', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '時策已平吳、會二郡，賁與策征廬江太守劉勳、江夏太守黃祖，軍旋，聞繇病死，過定豫章，上賁領太守，江表傳曰：時丹楊僮芝自署廬陵太守，策留賁弟輔領兵住南昌，策謂賁曰：「兄今據豫章，是扼僮芝咽喉而守其門戶矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-054-23', 'p0103', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '江夏太守黃祖遣將鄧龍將兵數千人入柴桑，瑜追討擊，生虜龍送吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-054-24', 'p0103', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '因其多務，勦除黃祖，進伐劉表，竟長江所極，據而有之，然後建號帝王以圖天下，此高帝之業也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-054-25', 'p0103', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '從征黃祖，祖令都督陳就逆以水軍出戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-26', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後拜盪寇中郎將，領零陵太守，從討劉勳於尋陽，進攻黃祖於沙羨，還鎮石城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-27', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從征劉勳，破黃祖，還討鄱陽，領樂安長，山越畏服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-28', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從策攻皖，又討劉勳於尋陽，伐黃祖於江夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-29', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '建安十三年，權討黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-30', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '止不攻劫，頗讀諸子，乃往依劉表，因居南陽，不見進用，後轉託黃祖，祖又以凡人畜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-31', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '黃祖在夏口，軍不得過，乃留依祖，三年不禮之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-32', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '圖之之計，宜先取黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-33', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '行入右江，斬黃祖將張碩，盡獲船人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-34', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫權統事，以為別部司馬，授兵五百人，守柴桑長，拒黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-057-35', 'p0103', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '江表傳曰：策討黃祖，旋軍欲過取豫章，特請翻語曰：「華子魚自有名字，然非吾敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-062-36', 'p0103', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '策薨，權為討虜將軍，以綜為金曹從事，從討黃祖，拜鄂長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-063-37', 'p0103', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '初，權在吳，欲討黃祖，範曰：「今茲少利，不如明年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-058-0', 'p0104', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '英雄記云，袁紹使張景明、郭公則、高元才等說韓馥，使讓兾州與紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-070-1', 'p0104', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會兾州牧同郡韓馥遣騎迎之，彧乃獨將宗族從馥，留者後多為董卓將李傕所殺略焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-072-2', 'p0104', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '以尚書韓馥為兾州刺史，英雄記馥字文節，潁川人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-073-3', 'p0104', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '二年，兾州刺史韓馥、勃海太守袁紹及山東諸將議，以朝廷幼沖，時獻帝年十歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-073-4', 'p0104', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '逼迫韓馥，竊奪其州，矯刻金玉，以為印璽，每有所下，輒皁囊施檢，文稱詔書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-5', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '初平元年，紹遂以勃海起兵，與從弟後將軍術、兾州牧韓馥、馥字文節，潁川人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-6', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '韓馥見人情歸紹，忌其得衆，恐將圖己，常遣從事守紹門，不聽發兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-7', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '今兾部強實，而韓馥庸才，可密要公孫瓚將兵南下，馥聞必駭懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-8', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '』」並以正直不得志於韓馥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-9', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會故兾州牧韓馥懷挾逆謀，欲專權埶，絕臣軍糧，不得踵係，至使猾虜肆毒，害及一門，尊卑大小，同日并戮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-10', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '金鼓未震，狡敵知亡，故韓馥懷懼，謝咎歸土，張楊、黑山同時乞降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-108-11', 'p0104', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '」吳書載韓馥與袁術書曰：「凶出於代郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-001-12', 'p0104', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初平元年春正月，後將軍袁術、兾州牧韓馥、英雄記曰：馥字文節，潁川人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-001-13', 'p0104', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹與韓馥謀立幽州牧劉虞為帝，太祖拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-001-14', 'p0104', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋七月，袁紹脅韓馥，取兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-001-15', 'p0104', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '獻帝起居注曰：公上言「大將軍鄴侯袁紹前與兾州牧韓馥立故大司馬劉虞，刻作金璽，遣故任長畢瑜詣虞，為說命錄之數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-006-16', 'p0104', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓信任尚書周毖、城門校尉伍瓊等，用其所舉韓馥、劉岱、孔伷、張咨、張邈等出宰州郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-006-17', 'p0104', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹自號車騎將軍，主盟，與兾州牧韓馥立幽州牧劉虞為帝，遣使奉章詣虞，虞不敢受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-006-18', 'p0104', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '仕州別駕，舉茂才，歷二縣令，又為韓馥別駕，表拜騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-007-19', 'p0104', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臣松之案英雄記云：「袁紹使張景明、郭公則、高元才等說韓馥，使讓兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-008-20', 'p0104', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹、韓馥議，以為少帝制於姦臣，天下無所歸心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-008-21', 'p0104', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '韓馥之迫，竊其虛位，矯命詔恩，刻金印玉璽，每下文書，皁囊施檢，文曰『詔書一封，邟口浪反鄉侯印』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-010-22', 'p0104', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」鄉人多懷土猶豫，會兾州牧同郡韓馥遣騎迎之，莫有隨者，彧獨將宗族至兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-012-23', 'p0104', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '紹劫奪韓馥位，遂據兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-017-24', 'p0104', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '漢末應募討黃巾，為軍司馬，屬韓馥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-038-25', 'p0104', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '進用潁川荀爽、韓融、陳紀等為公、卿、郡守，拜尚書韓馥為兾州牧，侍中劉岱為兖州刺史，潁川張咨為南陽太守，陳留孔伷為豫州刺史，東郡張邈為陳留太守，而遷靖巴郡太守，不就，補御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-008-full-0', 'p0105', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-008-full-1', 'p0105', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '辛未，司隷校尉袁紹勒兵收偽司隷校尉樊陵、河南尹許相及諸閹人，無少長皆斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-008-2', 'p0105', 'houhanshu', 'a03-008', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-008-3', 'p0105', 'houhanshu', 'a03-008', '《後漢書·卷八》', '辛未，司隷校尉袁紹勒兵收偽司隷校尉樊陵、河南尹許相及諸閹人，無少長皆斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-4', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '輕財好施，以任俠聞，為袁紹河內太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-5', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁紹及公孫瓉戰于界橋，今貝州宗城縣東有古界城，近枯漳水，則界橋在此也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-6', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，袁紹遣將麴義與公孫瓉戰於鮑丘，鮑丘，水名，出北塞中，南流經九莊嶺東，俗謂之大榆河。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-7', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，袁紹自為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-8', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '四年春三月，袁紹攻公孫瓉于易京，獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-9', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '曹操與袁紹戰於官度，裴松之北征記曰：「中牟臺下臨汴水，是為官度，袁紹、曹操壘尚存焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-10', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '七年夏五月庚戌，袁紹薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-035-11', 'p0105', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '時大將軍袁紹緫兵兾州，遣使要玄，大會賔客，玄最後至，乃延升上坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-035-12', 'p0105', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '時袁紹與曹操相拒於官度，官度，津名也，在今鄭州中牟縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-048-13', 'p0105', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '劭畏操誅，弃郡奔兾州牧袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-048-14', 'p0105', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '二年，詔拜劭為袁紹軍謀校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-049-15', 'p0105', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '并州刺史高幹，袁紹甥也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-052-16', 'p0105', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '獻帝初，鈞與袁紹俱起兵山東，董卓以是收烈付郿獄，錮之，鋃鐺鐵鎖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-17', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '勳時與宗正劉虞、佐軍校尉袁紹同典禁兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-18', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '行至河閒而值幽兾交兵，行塗阻絕，因寓於袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-19', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '在事二年，袁紹憚其能，徙為東郡太守，都東武陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-20', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '英雄記云，袁紹使張景明、郭公則、高元才等說韓馥，使讓兾州與紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-21', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '進敗，揚遂以所將兵攻上黨，仍略諸縣，衆至數千，又與袁紹合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-22', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '足下徼利於境外，臧洪投命於君親；吾子託身於盟主，盟主謂袁紹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-23', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '城中粮盡，外無援救，洪自度不免，呼吏士謂曰：「袁紹無道，所圖不軌，且不救洪郡將，洪於大義，不得不死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-062-24', 'p0105', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '建安初，袁紹為太尉，讓於紀；紀不受，拜大鴻臚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-064-25', 'p0105', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '是時袁紹、曹操與公孫瓚爭兾州，紹及操聞歧至，皆自將兵數百里奉迎，歧深陳天子恩德，宜罷兵安人之道，又移書公孫瓚，為言利害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-067-26', 'p0105', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '袁紹慕之，私與往來，結為奔走之友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-068-27', 'p0105', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '同郡袁紹，公族豪俠，去濮陽令歸，車徒甚盛，將入郡界，乃謝遣賔客，曰：「吾輿服豈可使許子將見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-28', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '是時置西園八校尉，以小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎都尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍校尉，淳于瓊為佐軍校尉，又有左右校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-29', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '進陰知其謀，乃上遣袁紹東擊徐兖二州兵，須紹還，即戎事，以稽行期。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-30', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '袁紹亦素有謀，因進親客張津勸之曰：「黃門常侍權重日乆，又與長樂太后專通姦利，靈帝母董太后居長樂宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-31', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '袁紹復說進曰：「前竇武欲誅內寵而反為所害者，以其言語漏泄，而五營百官服畏中人故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-32', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」袁紹勸進便於此決之，至于再三。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-33', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '袁紹與叔父隗矯詔召樊陵、許相，斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-34', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '公業等與侍中伍瓊、卓長史何顒共說卓，以袁紹為勃海太守，以發山東之謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-35', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '袁紹傳，熙，紹之中子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-36', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧比至兾州，而袁紹已奪馥位，紹待彧以上賔之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-37', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '袁紹旣兼河朔之地，有驕氣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-38', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '五年，袁紹率大衆以攻許，操與相距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-39', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '少府孔融謂彧曰：「袁紹地廣兵彊，田豐、許攸智計之士為其謀，先賢行狀：「豐字元皓，鉅鹿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-40', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」後皆如彧之籌，事在袁紹傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-41', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '十二年，操上書表彧曰：「昔袁紹作逆，連兵官度，時衆寡糧單，圖欲還許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-071-42', 'p0105', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '其後諸賊多為袁紹所定，事在紹傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-072-43', 'p0105', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '及帝崩，大將軍何進、司隷校尉袁紹謀誅閹宦，而太后不許，乃私呼卓將兵入朝，以脅太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-072-44', 'p0105', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初平元年，馥等到官，與袁紹之徒十餘人，各興義兵，同盟討卓，而伍瓊、周珌陰為內主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-45', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '二年，兾州刺史韓馥、勃海太守袁紹及山東諸將議，以朝廷幼沖，時獻帝年十歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-46', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '和尋得逃術還北，復為袁紹所留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-47', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '瓚乃誣虞前與袁紹等欲稱尊號，脅訓斬虞於薊市。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-48', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '術遣越隨其將孫堅，擊袁紹將周昕，越為流矢所中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-49', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '今車騎將軍袁紹，託承先軌，爵任崇厚，而性本淫亂，情行浮薄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-50', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '烏桓峭王感虞恩德，率種人及鮮卑七千餘騎，共輔南迎虞子和，與袁紹將麴義合兵十萬，共攻瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-51', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '建安三年，袁紹復大攻瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-52', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '袁紹字本初，汝南汝陽人，司徒湯之孫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-53', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八人，謂之西園軍，皆統於碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-54', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '山陽公載記曰：「卓以袁紹棄節，改第一葆為赤旄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-55', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '袁紹不達大體，恐懼出奔，非有它志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-56', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '後袁紹至，馥從事十人棄馥去，唯恐在後，獨武、純杖刀拒，兵不能禁，紹後令田豐殺此二人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-57', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '袁紹孤客窮軍，仰我鼻息，譬如嬰兒在股掌之上，絕其哺乳，立可餓殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-58', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '魏志曰：「琳字孔璋，廣陵人，避難兾州，袁紹使典文章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-59', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」典論曰：「袁紹妻劉氏性酷妒，紹死，僵尸未殯，寵妾五人盡殺之，為死者有知，當復見紹於地下，乃髡頭墨面，以毀其形。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-075-60', 'p0105', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '然而河北異謀於黑山，謂袁紹為兾州牧，與黑山賊相連。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-075-61', 'p0105', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '有頃，布得走投袁紹，紹與布擊張燕於常山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-075-62', 'p0105', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '及袁紹為盟主，有驕色，邈正義責之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-078-63', 'p0105', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '雖袁紹龔行，芟夷無餘，然以暴易亂，亦何云及！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-078-64', 'p0105', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '中軍校尉袁紹說大將軍何進，令誅中官以恱天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-090-65', 'p0105', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '建安初，兾州牧袁紹與前將軍公孫瓚相持不決，蹋頓遣使詣紹求和親，遂遣兵助擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-090-66', 'p0105', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '袁紹因寵慰柔，以安北邊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-102-67', 'p0105', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '中平六年，宮車晏駕，大將軍何進令司隷校尉袁紹私募兵千餘人，陰跱雒陽城外，竊呼并州牧董卓使將兵至京都，共誅中官，對戰南、北宮闕下，死者數千人，燔燒宮室，遷都西京。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-102-68', 'p0105', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '」至六年，司隷校尉袁紹誅滅中官，大將軍部曲將吳匡攻殺車騎將軍何苗，死者數千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-103-69', 'p0105', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '是時靈帝新棄羣臣，大行尚在梓宮，大將軍何進與佐軍校尉袁紹等共謀欲誅廢中官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-103-70', 'p0105', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '建安三年，袁紹攻瓚，瓚大敗，縊其姊妹妻子，引火自焚，紹兵趣登臺斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-111-71', 'p0105', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '東有地烏巢，曹公破袁紹處。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-118-72', 'p0105', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '故焉牧益土，造帝服於岷、峨；袁紹取兾，下制書於燕、朔；劉表荊南，郊天祀地；魏祖據兖，遂構皇業：漢之殄滅，禍源乎此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-73', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '大將軍何進與袁紹謀誅宦官，太后不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-74', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹之在勃海，馥恐其興兵，遣數部從事守之，不得動搖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-75', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '勃海太守袁紹、陳留太守張邈、東郡太守橋瑁、英雄記曰：瑁字元偉，玄族子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-76', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹與韓馥謀立幽州牧劉虞為帝，太祖拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-77', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋七月，袁紹脅韓馥，取兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-78', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹因表太祖為東郡太守，治東武陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-79', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是以袁紹為太尉，紹恥班在公下，不肯受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-80', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹之在河北，軍人仰食桑椹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-81', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '獻帝春秋曰：袁紹叛卒詣公云：「田豐使紹早襲許，若挾天子以令諸侯，四海可指麾而定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-82', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏書曰：袁紹宿與故太尉楊彪、大長秋梁紹、少府孔融有隙，欲使公以他過誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-83', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張楊將楊醜殺楊，眭固又殺醜，以其衆屬袁紹，屯射犬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-84', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是時袁紹旣并公孫瓚，兼四州之地，衆十餘萬，將進軍攻許，諸將以為不可敵，公曰：「吾知紹之為人，志大而智小，色厲而膽薄，忌克而少威，兵多而分畫不明，將驕而政令不一，土地雖廣，糧食雖豐，適足以為吾奉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-85', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公將自東征備，諸將皆曰：「與公爭天下者，袁紹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-86', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹雖有大志，而見事遟，必不動也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-87', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹運穀車數千乘至，公用荀攸計，遣徐晃、史渙邀擊，大破之，盡燒其車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-88', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '獻帝起居注曰：公上言「大將軍鄴侯袁紹前與兾州牧韓馥立故大司馬劉虞，刻作金璽，遣故任長畢瑜詣虞，為說命錄之數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-89', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '諸將皆疑，荀攸勸公許之，魏書曰：公云：「我攻呂布，表不為寇，官渡之役，不救袁紹，此自守之賊也，宜為後圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-90', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，袁紹以甥高幹領并州牧，公之拔鄴，幹降，遂以為刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-91', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹皆立其酋豪為單于，以家人子為己女，妻焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-92', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '及袁紹與弟術喪母，歸葬汝南，儁與公會之，會者三萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-93', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '及至袁紹據河北，兵勢彊盛，孤自度勢，實不敵之，但計投死為國，以義滅身，足垂於後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-94', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹逆亂天常，謀危社稷，憑恃其衆，稱兵內侮，當此之時，王師寡弱，天下寒心，莫有固志，君執大節，精貫白日，奮其武怒，運其神策，致屆官渡，大殲醜類，詩曰：「致天之屆，于牧之野。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-95', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '傅子曰：漢末王公，多委王服，以幅巾為雅，是以袁紹、崔豹之徒，雖為將帥，皆著縑巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-96', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '評曰：漢末，天下大亂，雄豪並起，而袁紹虎眎四州，彊盛莫敵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-005-97', 'p0105', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '建安中，袁紹為中子熈納之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-98', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '大將軍何進與司隷校尉袁紹謀誅諸閹官，太后不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-99', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獲袁紹豫州從事李延，煑殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-100', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹字本初，汝南汝陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-101', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹孤客窮軍，仰我鼻息，譬如嬰兒在股掌之上，絕其哺乳，立可餓殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-102', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '匡受袁紹旨，收班繫獄，欲殺之以徇軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-103', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹起義，卑辭厚幣以招致豐，豐以王室多難，志存匡救，乃應紹命，以為別駕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-104', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹領兾州，委以腹心之任，以為治中別駕，并總幕府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-105', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹遣袁遺領州，敗散，奔沛國，為兵所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-106', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '天子都許，表雖遣使貢獻，然北與袁紹相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-107', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太祖與袁紹方相持於官渡，紹遣人求助，表許之而不至，亦不佐太祖，欲保江漢間，觀天下變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-108', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '夫以曹公之明哲，天下賢俊皆歸之，其勢必舉袁紹，然後稱兵以向江漢，恐將軍不能禦也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-109', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹、劉表咸有威容、器觀，知名當世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-007-110', 'p0105', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '北詣袁紹，紹與布擊張燕於常山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-007-111', 'p0105', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '袁紹旣為盟主，有驕矜色，邈正議責紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-007-112', 'p0105', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '呂布之捨袁紹從張楊也，過邈臨別，把手共誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-007-113', 'p0105', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '而袁紹見洪，又奇重之，與結分合好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-007-114', 'p0105', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臣松之案英雄記云：「袁紹使張景明、郭公則、高元才等說韓馥，使讓兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-115', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹、韓馥議，以為少帝制於姦臣，天下無所歸心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-116', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '今行車騎將軍袁紹，託其先軌，寇竊人爵，旣性暴亂，厥行淫穢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-117', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹又遣麴義及虞子和，將兵與輔合擊瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-118', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '」是以袁紹始北擊之時，瓚南界上別營自度守則不能自固，又知必不見救，是以或自殺其將帥，或為紹兵所破，遂令紹軍徑至其門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-119', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '漢晉春秋曰：袁紹與瓚書曰：「孤與足下，旣有前盟舊要，申以討亂之誓，愛過夷、叔，分著丹青，謂為流力同仇，足踵齊、晉，故解印釋紱，以北帶南，分割膏腴，以奉執事，此非孤赤情之明驗邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-120', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '將軍堅守曠日，袁紹要當自退；自退之後，四方之衆必復可合也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-121', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '英雄記曰：袁紹分部攻者掘地為道，穿穴其樓下，稍稍施木柱之，度足達半，便燒所施之柱，樓輒傾倒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-122', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '太祖與袁紹相拒於官渡，閻柔遣使詣太祖受事，遷護烏丸校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-123', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹破走，太祖喜，顧謂輔曰：「如前歲本初送公孫瓚頭來，孤自視忽然耳，而今克之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-124', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '太祖及袁紹等皆為校尉，屬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-125', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '靈帝紀曰：以虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融、馮芳為助軍校尉，夏牟、淳于瓊為左右校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-126', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹至河內，楊與紹合，復與匈奴單于於夫羅屯漳水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-127', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '其將楊醜殺楊以應太祖，楊將眭固殺醜，將其衆，欲北合袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-128', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹與公孫瓚爭兾州，燕遣將杜長等助瓚，與紹戰，為紹所敗，人衆稍散，太祖將定兾州，燕遣使求佐王師，拜平北將軍；率衆詣鄴，封安國亭侯，邑五百戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-129', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '太祖拒袁紹於官渡，繡從賈詡計，復以衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-009-130', 'p0105', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '及與袁紹戰於官渡，行督軍校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-009-131', 'p0105', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖與袁紹乆相持於官渡，紹遣劉備徇㶏彊諸縣，多舉衆應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-132', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '而袁紹已奪馥位，待彧以上賔之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-133', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '自太祖之迎天子也，袁紹內懷不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-134', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '今與公爭天下者，唯袁紹爾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-135', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '三年，太祖旣破張繡，東禽呂布，定徐州，遂與袁紹相拒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-136', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧第四兄諶，字友若，事見袁紹傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-137', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧別傳曰：太祖又表曰：「昔袁紹侵入郊甸，戰於官渡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-138', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '昔公在官渡與袁紹相持，恐增內顧之念，故不言爾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-139', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '顒旣奇太祖而知荀彧，袁紹慕之，與為奔走之友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-140', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '袁紹渡河追，卒與太祖遇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-141', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '是後，太祖拒袁紹於官渡，紹遣人招繡，并與詡書結援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-142', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '袁紹圍太祖於官渡，太祖糧方盡，問詡計焉出，詡曰：「公明勝紹，勇勝紹，用人勝紹，決機勝紹，有此四勝而半年不定者，但顧萬全故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-143', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '袁紹數遣使招命，又即授將軍印，因安輯所統，疇皆拒不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-144', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '及袁紹父子威力加於朔野，遠結烏丸，與為首尾，前後召疇，終不陷撓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-145', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '臣松之以為田疇不應袁紹父子之命，以其非正也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-146', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '袁紹又辟脩除即墨令，後復為譚別駕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-147', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '袁紹前後辟命，不應，移居上黨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-148', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '胡昭始避地兾州，亦辭袁紹之命，遁還鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-149', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '魏氏春秋曰：袁紹之敗也，融與太祖書曰：「武王伐紂，以妲己賜周公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-150', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '南陽許攸、魏略曰：攸字子遠，少與袁紹及太祖善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-151', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '今袁紹、劉表，雖士民衆彊，皆無經遠之慮，未有樹基建本者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-152', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '時太子未定，而臨菑侯植有寵，玠密諫曰：「近者袁紹以嫡庶不分，覆宗滅國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-153', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '信知卓必為亂，勸袁紹襲卓，紹畏卓不敢發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-154', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '太祖與袁紹表信行破虜將軍，韜裨將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-013-155', 'p0105', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太祖在官渡，與袁紹相持，繇送馬二千餘匹給軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-156', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '是時岱與袁紹、公孫瓚和親，紹令妻子居岱所，瓚亦遣從事范方將騎助岱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-157', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '夫公孫瓚，非袁紹之敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-158', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '於是袁紹使人說太祖連和，欲使太祖遷家居鄴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-159', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '時昱使適還，引見，因言曰：「竊聞將軍欲遣家，與袁紹連和，誠有之乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-160', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '夫袁紹據燕、趙之地，有并天下之心，而智不能濟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-161', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '今聞將軍欲遣家往鄴，將北面而事袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-162', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '夫以將軍之聦明神武，而反不羞為袁紹之下，竊為將軍恥之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-163', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昱不肯，曰：「袁紹擁十萬衆，自以所向無前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-164', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '初，北見袁紹，謂紹謀臣辛評、郭圖曰：「夫智者審於量主，故百舉百全而功名可立也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-165', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '孫策轉鬬千里，盡有江東，聞太祖與袁紹相持於官渡，將渡江北襲許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-166', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：太祖欲速征劉備，議者懼軍出，袁紹擊其後，進不得戰而退失所據。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-167', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '從破袁紹，紹死，又從討譚、尚於黎陽，連戰數克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-168', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '諸將欲乘勝遂攻之，嘉曰：「袁紹愛此二子，莫適立也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-169', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '且袁紹有恩於民夷，而尚兄弟生存。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-170', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '舉孝廉，除廮陶長、栢人令，袁紹以為參軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-171', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '袁紹遣將顏良攻東郡，又徙昭為魏郡太守，從討良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-172', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '袁紹同族春卿為魏郡太守，在城中，其父元長在楊州，太祖遣人迎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-173', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '曄進曰：「明公以步卒五千，將誅董卓，北破袁紹，南征劉表，九州百郡，十并其八，威震天下，勢慴海外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-174', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '自破袁紹，北拔柳城，南向江、漢，荊州交臂，威震天下，民無他志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-015-175', 'p0105', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖方有袁紹之難，謂馥可任以東南之事，遂表為揚州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-016-176', 'p0105', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '後袁紹在兾州，亦貪祗，欲得之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-177', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '袁紹破，別遣遼定魯國諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-178', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '渡河攻獲嘉，還，從擊袁紹於官渡，力戰，斬紹將淳于瓊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-179', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖初征袁紹，紹兵盛，禁願為先登。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-180', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖與袁紹相拒於官渡，漢晉春秋曰：郃說紹曰：「公雖連勝，然勿與曹公戰也，密遣輕騎鈔絕其南，則兵自敗矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-181', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '臣松之案武紀及袁紹傳並云袁紹使張郃、高覽攻太祖營，郃等聞淳于瓊破，遂來降，紹衆於是大潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-182', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與曹洪擊彊賊祝臂，破之，又與史渙擊袁紹運車於故市，功最多，封都亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-183', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '初，清河朱靈為袁紹將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-184', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '九州春秋曰：初，清河季雍以鄃叛袁紹而降公孫瓚，瓚遣兵衞之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-018-185', 'p0105', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '時太祖與袁紹相拒官渡，典率宗族及部曲輸穀帛供軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-018-186', 'p0105', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖與袁紹相拒於官渡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-018-187', 'p0105', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '詔曰：「昔袁紹之難，自許、蔡以南，人懷異心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-018-188', 'p0105', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '時太祖方與袁紹相拒，而霸數以精兵入青州，故太祖得專事紹，不以東方為念。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-018-189', 'p0105', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '袁紹所置中郎將郭祖、公孫犢等數十輩，保山為寇，百姓苦之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-021-190', 'p0105', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太祖置酒漢濵，粲奉觴賀曰：「方今袁紹起河北，杖大衆，志兼天下，然好賢而不能用，故奇士去之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-021-191', 'p0105', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '琳避難兾州，袁紹使典文章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-021-192', 'p0105', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太祖征袁紹，而劉表為紹援，關中諸將又中立。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-021-193', 'p0105', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '夫夷狄之臣，不當兾州之卒，權、備之籍，不比袁紹之業，然本初以亡，而二寇未捷，非闇弱於今而智武於昔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-022-194', 'p0105', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '後太祖與袁紹相拒於官渡，表舉州以應紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-022-195', 'p0105', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '當袁紹、公孫瓚交兵，幽兾饑荒，養寡嫂孤兄子，以學行見稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-023-196', 'p0105', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '袁紹在兾州，遣使迎汝南士大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-023-197', 'p0105', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '袁紹公族好名，為濮陽長，棄官來還，有副車從騎，將入郡界，紹乃歎曰：「吾之輿服，豈可使許子將見之乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-023-198', 'p0105', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '少孤苦，袁紹父子時，始為名吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-023-199', 'p0105', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時袁紹舉兵南侵，遣使招誘豫州諸郡，諸郡多受其命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-023-200', 'p0105', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '魏略曰：太祖北拒袁紹，時遠近無不私遺牋記，通意於紹者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-024-201', 'p0105', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '柔從兄幹，袁紹甥也，謝承後漢書曰：幹字元才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-026-202', 'p0105', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '時袁紹盛於河朔，而汝南紹之本郡，門生賔客布在諸縣，擁兵拒守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-026-203', 'p0105', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '公孫瓚使豫守東州令，瓚將王門叛瓚，為袁紹將萬餘人來攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-026-204', 'p0105', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '兾州牧袁紹辟為督軍從事，兼領烏丸突騎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-027-205', 'p0105', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '武皇帝克袁紹於官渡，自以所獲已多，不復追奔，懼挫威也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-030-206', 'p0105', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '會袁紹兼河北，乃撫有三郡烏丸，寵其名王而收其精騎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-030-207', 'p0105', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '袁紹與公孫瓚連戰不決，蹋頓遣使詣紹求和親，助紹擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-030-208', 'p0105', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '部落近塞，自袁紹據河北，中國人多亡叛歸之，教作兵器鎧楯，頗學文字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-209', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '為賊所破，往奔中郎將公孫瓚，瓚表為別部司馬，使為青州刺史田楷以拒兾州牧袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-210', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '袁紹攻公孫瓚，先主與田楷東屯齊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-211', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝春秋曰：陳登等遣使詣袁紹曰：「天降灾沴，禍臻鄙州，州將殂殞，生民無主，恐懼姦雄一旦承隙，以貽盟主日昃之憂，輒共奉故平原相劉備府君以為宗主，永使百姓知有依歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-212', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '袁術欲經徐州北就袁紹，曹公遣先主督朱靈、路招要擊術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-213', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '東海昌霸反，郡縣多叛曹公為先主，衆數萬人，遣孫乾與袁紹連和，曹公遣劉岱、王忠擊之，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-214', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公與袁紹相拒於官渡，汝南黃巾劉辟等叛曹公應紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-035-215', 'p0105', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '曹操比於袁紹，則名微而衆寡，然操遂能克紹，以弱為彊者，非惟天時，抑亦人謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-036-216', 'p0105', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '建安五年，曹公東征，先主奔袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-036-217', 'p0105', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主背曹公依袁紹、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-036-218', 'p0105', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '本屬公孫瓚，瓚遣先主為田楷拒袁紹，雲遂隨從，為先主主騎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-036-219', 'p0105', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '時袁紹稱兾州牧，瓚深憂州人之從紹也，善雲來附，嘲雲曰：「聞貴州人皆願袁氏，君何獨迴心，迷而能反乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-036-220', 'p0105', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '」先主就袁紹，雲見於鄴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-038-221', 'p0105', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主之背曹公，遣乾自結袁紹，將適荊州，乾又與麋笁俱使劉表，皆如意指。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-222', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '袁紹遣會稽周㬂為豫州刺史，來襲取州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-223', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '山陽公載記曰：瑀單騎走兾州，自歸袁紹，紹以為故安都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-224', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '建安五年，曹公與袁紹相拒於官渡，策陰欲襲許，迎漢帝，吳錄曰：時有高岱者，隱於餘姚，策命出使會稽丞陸昭逆之，策虛己候焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-225', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '案夏侯元讓與石威則書「袁紹破後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-226', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '又案袁紹以建安五年至黎陽，而策以四月遇害，而志云策聞曹公與紹相拒於官渡，謬矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-227', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '案魏武紀，武帝以建安四年已出屯官渡，乃策未死之前，乆與袁紹交兵，則國志所云不為謬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-054-228', 'p0105', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '江表傳曰：曹公新破袁紹，兵威日盛，建安七年，下書責權質任子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-054-229', 'p0105', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」魏書及九州春秋曰：曹公征荊州，孫權大懼，魯肅實欲勸權拒曹公，乃激說權曰：「彼曹公者，實嚴敵也，新并袁紹，兵馬甚精，乘戰勝之威，伐喪亂之國，克可必也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-059-230', 'p0105', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '臣松之以為袁紹、劉表謂尚、琮為賢，本有傳後之意，異於孫權旣以立和而復寵霸，坐生亂階，自構家禍，方之袁、劉，昏悖甚矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-059-231', 'p0105', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '近袁紹、劉表各有國土，土地非狹，人衆非弱，以適庶不分，遂滅其宗祀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a03-009-0', 'p0106', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十年春正月，曹操破袁譚於青州，斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a03-070-1', 'p0106', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '建安元年，為袁譚所攻，自春至夏，戰士所餘裁數百人，流矢雨集，戈矛內接。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a03-075-2', 'p0106', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術因欲北至青州從袁譚，曹操使劉備徼之，不得過，復走還壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a03-105-3', 'p0106', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '十年，曹操破袁譚於南皮；十一年，走袁尚於遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-001-4', 'p0106', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術自敗於陳，稍困，袁譚自青州遣迎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-001-5', 'p0106', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '濟師洪河，拓定四州，袁譚、高幹，咸梟其首，海盜奔迸，黑山順軌，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-006-6', 'p0106', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '將歸帝號於紹，欲至青州從袁譚，發病道死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-008-7', 'p0106', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '從破袁譚於南皮，復增邑凡二千戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-010-8', 'p0106', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '一旦生變，雖有善守者，轉相脅為非，則袁尚得寬其死，而袁譚懷貳，劉表遂保江、漢之閒，天下未易圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-010-9', 'p0106', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '七年，從討袁譚、尚於黎陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-010-10', 'p0106', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸曰：「佐治為袁譚乞降，王師自往平之，吾何知焉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-011-11', 'p0106', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '疇此舉止，良為進退無當，與王脩哭袁譚，貌同而心異也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-011-12', 'p0106', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '袁譚在青州，辟脩為治中從事，別駕劉獻數毀短脩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-011-13', 'p0106', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '傅子曰：太祖旣誅袁譚，梟其首，令曰：「敢哭之者戮及妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-012-14', 'p0106', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '遂為袁譚所攻，自春至夏，城小寇衆，流矢雨集。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-012-15', 'p0106', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '郡濵山海，黃巾未平，豪傑多背叛，袁譚就加以官位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-014-16', 'p0106', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」昱收山澤亡命，得精兵數千人，乃引軍與太祖會黎陽，討袁譚、袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-014-17', 'p0106', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '自在軍旅，十有餘年，行同騎乘，坐共幄席，東禽呂布，西取眭固，斬袁譚之首，平朔土之衆，踰越險塞，盪定烏丸，震威遼東，以梟袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-014-18', 'p0106', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會太祖討袁譚於南皮，以書招松，松舉雍奴、泉州、安次以附之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-015-19', 'p0106', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '會尚不能救鄴，破走至中山，而袁譚又追擊尚，尚走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-017-20', 'p0106', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從討袁譚、袁尚於黎陽，有功，行中堅將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-017-21', 'p0106', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從攻袁譚，譚破，別將徇海濵，破遼東賊柳毅等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-017-22', 'p0106', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從圍鄴，鄴定，從擊袁譚於南皮，先登，入譚東門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-017-23', 'p0106', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又從擊袁譚於渤海，別將軍圍雍奴，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-017-24', 'p0106', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從破袁譚於南皮，討平原叛賊，克之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-018-25', 'p0106', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖破袁譚於南皮，霸等會賀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-018-26', 'p0106', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '建安中，太祖討袁譚、尚於黎陽，譚遣郭援、高幹等略取河東，太祖使鍾繇率關中諸將討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-026-27', 'p0106', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太祖將討袁譚，而柳城烏丸欲出騎助譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-032-28', 'p0106', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '青州刺史袁譚，先主故茂才也，將步騎迎先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-052-29', 'p0106', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '然徽潛采聽，方與袁譚交爭，未有他意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a03-009-0', 'p0107', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九年秋八月戊寅，曹操大破袁尚，平兾州，自領兾州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a03-009-1', 'p0107', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月，遼東太守公孫康殺袁尚、袁熙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a03-090-2', 'p0107', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '袁尚與樓班、烏延等皆走遼東，遼東太守公孫康並斬送之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a03-105-3', 'p0107', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '十年，曹操破袁譚於南皮；十一年，走袁尚於遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-001-4', 'p0107', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」將北征三郡烏丸，諸將皆曰：「袁尚，亡虜耳，夷狄貪而無親，豈能為尚用？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-001-5', 'p0107', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '烏丸三種，崇亂二世，袁尚因之，逼據塞北，束馬縣車，一征而滅，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-005-6', 'p0107', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '世語曰：太祖下鄴，文帝先入袁尚府，有婦人被髮垢靣，垂涕立紹妻劉後，文帝問之，劉荅「是熈妻」，顧擥髮髻，以巾拭面，姿貌絕倫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-008-7', 'p0107', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁尚等奔遼東，康斬送尚首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-010-8', 'p0107', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前日公破袁尚，禽審配，海內震駭，必人人自恐不得保其土地，守其兵衆也；今使分屬兾州，將皆動心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-010-9', 'p0107', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '一旦生變，雖有善守者，轉相脅為非，則袁尚得寬其死，而袁譚懷貳，劉表遂保江、漢之閒，天下未易圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-010-10', 'p0107', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖之征袁尚也，高幹密遣兵謀襲鄴，衍逆覺，盡誅之，以功封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-011-11', 'p0107', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '遼東斬送袁尚首，令「三軍敢有哭之者斬」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-011-12', 'p0107', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '致使袁尚奔迸，授首遼東，皆疇之由也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-011-13', 'p0107', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '臣松之案田疇傳，疇為袁尚所辟，不被譚命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-013-14', 'p0107', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」其後匈奴單于作亂平陽，繇帥諸軍圍之，未拔；而袁尚所置河東太守郭援到河東，衆甚盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-013-15', 'p0107', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '濟水未半，擊，大破之，司馬彪戰略曰：袁尚遣高幹、郭援將兵數萬人，與匈奴單于寇河東，遣使與馬騰、韓遂等連和，騰等陰許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-014-16', 'p0107', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」昱收山澤亡命，得精兵數千人，乃引軍與太祖會黎陽，討袁譚、袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-014-17', 'p0107', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖將征袁尚及三郡烏丸，諸下多懼劉表使劉備襲許以討太祖，嘉曰：「公雖威震天下，胡恃其遠，必不設備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-014-18', 'p0107', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '自在軍旅，十有餘年，行同騎乘，坐共幄席，東禽呂布，西取眭固，斬袁譚之首，平朔土之衆，踰越險塞，盪定烏丸，震威遼東，以梟袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-014-19', 'p0107', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '後袁尚依烏丸蹋頓，太祖將征之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-015-20', 'p0107', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '袁尚拒太祖於黎陽，遣所置河東太守郭援、并州刺史高幹及匈奴單于取平陽，發使西與關中諸將合從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-015-21', 'p0107', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '建安中，袁尚領冀州，以孚為主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-017-22', 'p0107', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從討袁譚、袁尚於黎陽，有功，行中堅將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-017-23', 'p0107', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征袁尚於柳城，卒與虜遇，遼勸太祖戰，氣甚奮，太祖壯之，自以所持麾授遼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-021-24', 'p0107', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時聞公孫淵受孫權燕王之號，議者欲留淵計吏，遣兵討之，劭以為「昔袁尚兄弟歸淵父康，康斬送其首，是淵先世之効忠也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-025-25', 'p0107', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '及袁尚攻兄譚於平原，譚使毗詣太祖求和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-025-26', 'p0107', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '天以袁尚與明公，明公不取而伐荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-026-27', 'p0107', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '還鄴，遼東送袁尚首，縣在馬市，招覩之悲感，設祭頭下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-028-28', 'p0107', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '右北平烏丸單于寇婁敦、遼西烏丸都督率衆王護留等，昔隨袁尚奔遼東者，率衆五千餘人降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-030-29', 'p0107', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後袁尚敗奔蹋頓，憑其勢，復圖兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-030-30', 'p0107', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '右北平烏丸單于寇婁敦、遼西烏丸都督率衆王護留葉，昔隨袁尚奔遼西，聞儉軍至，率衆五千餘人降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-038-31', 'p0107', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後表與袁尚書，說其兄弟分爭之變，曰：「每與劉左將軍、孫公祐共論此事，未甞不痛心入骨，相為悲傷也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0108-a03-009-0', 'p0108', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月，遼東太守公孫康殺袁尚、袁熙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0108-a03-070-1', 'p0108', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，曹操攻屠鄴城，袁氏婦子多見侵略，而操子丕私納袁熙妻甄氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0108-a04-001-2', 'p0108', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是月，袁熙大將焦觸、張南等叛攻熙、尚，熙、尚奔三郡烏丸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-008-full-0', 'p0109', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月戊辰，中常侍張讓、段珪等殺大將軍何進，於是虎賁中郎將袁術燒東西宮，攻諸宦者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-008-1', 'p0109', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月戊辰，中常侍張讓、段珪等殺大將軍何進，於是虎賁中郎將袁術燒東西宮，攻諸宦者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-2', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」將作大匠吳脩、越騎校尉王瓌安集關東，後將軍袁術、河內太守王匡各執而殺之，英雄記曰：「匡字公節，太山人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-3', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅與董卓將胡軫戰於陽人，陽人，聚名，屬河南郡，故城在今汝州梁縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-4', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅攻劉表於襄陽，堅戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-5', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，袁術殺楊州刺史陳溫，據淮南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-6', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，楊州刺史劉繇與袁術將孫策戰于曲阿，策字伯符，孫堅子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-7', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二年春，袁術自稱天子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-031-8', 'p0109', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '時袁術屯兵壽春，部曲飢餓，遣使求委輸兵甲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-031-9', 'p0109', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '幼年曾謁袁術，懷橘墯地者也，有名稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-048-10', 'p0109', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '獻帝遷許，以廷尉徵，當詣京師，道為袁術所劫，授璆以上公之位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-048-11', 'p0109', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '袁術有僭盜意，乃拘堅妻求之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-050-full-12', 'p0109', 'houhanshu', 'a03-050-full', '《後漢書·卷五十》', '後袁術求糧於陳而俊拒絕之，術忿恚，遣客詐殺俊及寵，陳由是破敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-050-full-13', 'p0109', 'houhanshu', 'a03-050-full', '《後漢書·卷五十》', '袁術使部曲將張闓陽私行到陳，之俊所，俊往從飲酒，因詐殺俊，一郡吏人哀號如喪父母。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-050-14', 'p0109', 'houhanshu', 'a03-050', '《後漢書·卷五十》', '後袁術求糧於陳而俊拒絕之，術忿恚，遣客詐殺俊及寵，陳由是破敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-050-15', 'p0109', 'houhanshu', 'a03-050', '《後漢書·卷五十》', '袁術使部曲將張闓陽私行到陳，之俊所，俊往從飲酒，因詐殺俊，一郡吏人哀號如喪父母。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-054-16', 'p0109', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '時袁術僭亂，操託彪與術婚姻，誣以欲圖廢置，奏收下獄，劾以大逆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-054-17', 'p0109', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '且以袁術之甥，慮為後患，遂因事殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-066-18', 'p0109', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '乃上護羌校尉楊瓚行左將軍事，執金吾士孫瑞為南陽太守，並將兵出武關道，以討袁術為名，實欲分路征卓，而後拔天子還洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-069-19', 'p0109', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '袁術與匡共斫攻之，中黃門持兵守閤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-070-20', 'p0109', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '事洩，顒等被執，公業脫身自武關走，東歸袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-070-21', 'p0109', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，太傅馬日磾奉使山東，及至淮南，數有意於袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-070-22', 'p0109', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '又袁術僭逆，非一朝一夕，日磾隨從，周旋歷歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-070-23', 'p0109', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」前以露袁術之罪，今復下劉表之事，是使跛牂欲闚高岸，天險可得而登也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-072-24', 'p0109', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」卓未至而何進敗，虎賁中郎將袁術乃燒南宮，欲討宦官，而中常侍段珪等山陽公載記「段」字作「殷」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-072-25', 'p0109', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃使人誣衞尉張溫與袁術交通，遂笞溫於市，殺之，以塞天變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-072-26', 'p0109', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」奉、暹奔袁術，遂縱暴楊、徐閒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-073-27', 'p0109', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '道由南陽，後將軍袁術聞其狀，遂質和，使報虞遣兵俱西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-073-28', 'p0109', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '瓚旣諫劉虞遣兵就袁術，而懼術知怨之，乃使從弟越將千餘騎詣術自結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-074-29', 'p0109', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」袁術亦執殺陰循，惟韓融以名德免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-074-30', 'p0109', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '時袁術僭亂，操託彪與術婚姻，誣以欲圖廢置，奏收下獄，劾以大逆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-31', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術字公路，汝南汝陽人，司空逢之子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-32', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術登城，見而恱之，遂納焉，甚愛幸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-33', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '邈詣袁術求救，留超將家屬屯雍丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-34', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '時劉備領徐州，居下邳，與袁術相拒於淮上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-35', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '尚依袁術，術僭號，欲以尚為太尉，不敢顯言，私使諷之，術亦不敢強也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-36', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '今與袁術結姻，必受不義之名，將有累卵之危矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-37', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術怒布殺韓胤，遣其大將張勳、橋蕤等與韓暹、楊奉連埶，步騎數萬，七道攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-38', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '今袁術造逆，宜共誅討，柰何與賊還來伐布？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-39', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '建安二年，布遂復從袁術，遣順攻劉備於沛，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-40', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '而潛遣人求救於袁術，自將千餘騎出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-076-41', 'p0109', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '時袁術據淮南，繇乃移居曲阿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-076-42', 'p0109', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '袁術遣孫策攻破繇，因奔豫章，病卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-108-43', 'p0109', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '」吳書載韓馥與袁術書曰：「凶出於代郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-110-44', 'p0109', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '地道記曰有公路城，袁術所築。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-111-45', 'p0109', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '匡人之亭，曹公破袁術處。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-46', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初平元年春正月，後將軍袁術、兾州牧韓馥、英雄記曰：馥字文節，潁川人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-47', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '英雄記曰：紹後用遺為揚州刺史，為袁術所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-48', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術與紹有隙，術求援於公孫瓚，瓚使劉備屯高唐，單經屯平原，陶謙屯發干，以逼紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-49', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是歲，孫策受袁術使渡江，數年閒遂有江東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-50', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '邈詣袁術請救，為其衆所殺，兖州平，遂東略陳地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-51', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '建安元年春正月，太祖軍臨武平，袁術所置陳相袁嗣降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-52', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖將迎天子，諸將或疑，荀彧、程昱勸之，乃遣曹洪將兵西迎，衞將軍董承與袁術將萇奴拒險，洪不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-53', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '汝南、潁川黃巾何儀、劉辟、黃邵、何曼等，衆各數萬，初應袁術，又附孫堅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-54', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '冬十月，公征奉，奉南奔袁術，遂攻其梁屯，拔之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-55', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術在江、淮，取給蒲蠃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-56', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術欲稱帝於淮南，使人告呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-57', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」呂布復為袁術使高順攻劉備，公遣夏侯惇救之，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-58', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術自敗於陳，稍困，袁譚自青州遣迎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-59', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '被徵當還，為袁術所劫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-60', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '又袁術僭號於九江，下皆稱臣，名門曰建號門，衣被皆為天子之制，兩婦預爭為皇后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-61', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術僭逆，肆於淮南，懾憚君靈，用丕顯謀，蘄陽之役，橋蕤授首，稜威南邁，術以隕潰，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-003-62', 'p0109', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '獻帝傳曰：朗父名宜祿，為呂布使詣袁術，術妻以漢宗室女。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-005-63', 'p0109', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '袁術傳太祖凶問，時太祖左右至洛者皆欲歸，后止之曰：「曹君吉凶未可知，今日還家，明日若在，何靣目復相見也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-64', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '故太尉張溫時為衞尉，素不善卓，卓心怨之，因天有變，欲以塞咎，使人言溫與袁術交關，遂笞殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-65', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '先是，太祖遣劉備詣徐州拒袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-66', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術字公路，司空逢子，紹之從弟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-67', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '坐櫺牀上，歎息良乆，乃大咤曰：「袁術至於此乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-68', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '司馬彪戰略曰：劉表之初為荊州也，江南宗賊盛，袁術屯魯陽，盡有南陽之衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-69', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表曰：「宗賊甚盛，而衆不附，袁術因之，禍今至矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-70', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術勇而無斷，蘇代、具羽皆武人，不足慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-71', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術之在南陽也，與孫堅合從，欲襲奪表州，使堅攻表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-72', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術奢淫放肆，榮不終己，自取之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-73', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術無豪芒之功，纖介之善，而猖狂于時，妄自尊立，固義夫之所扼腕，人鬼之所同疾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-74', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '將數百騎出武關，欲詣袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-75', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '邈詣袁術請救未至，自為其兵所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-76', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '獻帝春秋曰：袁術議稱尊號，邈謂術曰：「漢據火德，絕而復揚，德澤豐流，誕生明公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-77', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '英雄記曰：布初入徐州，書與袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-78', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布問性，言「萌受袁術謀，謀者悉誰？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-79', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '使人於山陽界亡失文字，太祖又手書厚加慰勞布，說起迎天子，當平定天下意，并詔書購捕公孫瓚、袁術、韓暹、楊奉等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-80', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '重見購捕袁術等詔書，布當以命為效。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-81', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '袁術稱天子，將軍止之，而使不通章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-82', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '今袁術造逆，當共誅討，奈何與賊臣還共伐布？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-008-83', 'p0109', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '」　吳書曰：馥以書與袁術，云帝非孝靈子，欲依絳、灌誅廢少主，迎立代王故事；稱虞功德治行，華夏少二，當今公室枝屬皆莫能及。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-008-84', 'p0109', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '和道經袁術，為說天子意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-008-85', 'p0109', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '臣又每得後將軍袁術書，云紹非術類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-009-86', 'p0109', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '袁術聞而壯之，以為騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-009-87', 'p0109', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖之破袁術，仁所斬獲頗多。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-009-88', 'p0109', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '興平末，袁術部黨與太祖攻劫，太祖出，為寇所追，走入秦氏，伯南開門受之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-010-89', 'p0109', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '破布，然後南結揚州，共討袁術，以臨淮、泗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-010-90', 'p0109', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '以督軍御史中丞詣揚州討袁術，會術病卒，因以為揚州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-010-91', 'p0109', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '而袁術亦豪俠，與紹爭名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-010-92', 'p0109', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '布驍猛，又恃袁術，若從橫淮、泗間，豪傑必應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-011-93', 'p0109', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '後避地江、淮間，為袁術所命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-011-94', 'p0109', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '袁術備禮招請，範稱疾不往，術不彊屈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-012-95', 'p0109', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '續漢書曰：太尉楊彪與袁術婚姻，術僭號，太祖與彪有隙，因是執彪，將殺焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-012-96', 'p0109', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '後袁術至壽春，辟之，夔不應，然遂為術所留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-012-97', 'p0109', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '時有傳袁術軍亂者，太祖問夔曰；「君以為信不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-014-98', 'p0109', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '後又遣備至徐州要擊袁術，昱與郭嘉說太祖曰：「公前日不圖備，昱等誠不及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-014-99', 'p0109', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會太祖使備要擊袁術，嘉與程昱俱駕而諫太祖曰：「放備，變作矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-014-100', 'p0109', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '奉、暹失衆，東降袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-014-101', 'p0109', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖令劉備拒袁術，昭曰：「備勇而志大，關羽、張飛為之羽翼，恐備之心未可得論也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-015-102', 'p0109', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '避亂揚州，建安初，說袁術將戚寄、秦翊，使率衆與俱詣太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-016-103', 'p0109', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '後將軍袁術以為揚州刺史，未至官，道卒，時年四十二。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-016-104', 'p0109', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '渾將泰小子袤避難淮南，袁術賔禮甚厚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-018-105', 'p0109', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '初平中，以衆隨太祖，破黃巾於壽張，又從擊袁術，征徐州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-022-106', 'p0109', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '時陶謙病死，徐州迎備，備欲往，羣說備曰：「袁術尚彊，今東，必與之爭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-022-107', 'p0109', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '避亂江東及東城，辭孫策、袁術之命，還本郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-024-108', 'p0109', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '避袁術命召，徙居山都之山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-032-109', 'p0109', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」袁術來攻先主，先主拒之於盱眙、淮陰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-032-110', 'p0109', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '英雄記曰：備留張飛守下邳，引兵與袁術戰於淮陰石亭，更有勝負。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-032-111', 'p0109', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '收散卒，東取廣陵，與袁術戰，又敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-032-112', 'p0109', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '袁術欲經徐州北就袁紹，曹公遣先主督朱靈、路招要擊術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-032-113', 'p0109', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣松之案：魏武帝遣先主統諸將要擊袁術，郭嘉等並諫，魏武不從，其事顯然，非因種菜遁逃而去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-035-114', 'p0109', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮早孤，從父玄為袁術所署豫章太守，玄將亮及亮弟均之官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-038-115', 'p0109', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '迫於袁術放命圮族，扇動羣逆，津塗四塞，雖縣心北風，欲行靡由。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-038-116', 'p0109', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '建安元年，呂布乘先主之出拒袁術，襲下邳，虜先主妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-117', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '獻帝春秋曰：袁術表堅假中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-118', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '前到魯陽，與袁術相見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-119', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '山陽公載記曰：袁術將僭號，聞堅得傳國璽，乃拘堅夫人而奪之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-120', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '會次兄九江太守昂為袁術所攻，㬂往助之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-121', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」　江表傳曰：策徑到壽春見袁術，涕泣而言曰：「亡父昔從長沙入討董卓，與明使君會於南陽，同盟結好；不幸遇難，勳業不終。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-122', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時袁術僭號，策以書責而絕之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-123', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」又詔勑曰：「故左將軍袁術不顧朝恩，坐創凶逆，造合虛偽，欲因兵亂，詭詐百姓，始聞其言以為不然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-124', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '興平二年十二月二十日，於吳郡曲阿得袁術所呈表，以臣行殄寇將軍；至被詔書，乃知詐擅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-125', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：策被詔勑，與司空曹公、衞將軍董承、益州牧劉璋等并力討袁術、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-049-126', 'p0109', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '時袁術在淮南，繇畏憚，不敢之州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-050-127', 'p0109', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '袁術上景領丹楊太守，討故太守周昕，遂據其郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-050-128', 'p0109', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '策表琨領丹楊太守，會吳景委廣陵來東，復為丹楊守，江表傳曰：初，袁術遣從弟胤為丹楊，策令琨討而代之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-050-129', 'p0109', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '吳錄曰：袁夫人者，袁術女也，有節行而無子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-130', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '袁術之在淮南也，昕惡其淫虐，絕不與通。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-131', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '獻帝春秋曰：袁術遣吳景攻昕，未拔，景乃募百姓敢從周昕者死不赦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-132', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '後袁術徙壽春，賁又依之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-133', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '江表傳曰：袁術以吳景守廣陵，策族兄香亦為術所用，作汝南太守，而令賁為將軍，領兵在壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-134', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '後為袁術驅馳，加征南將軍，死於壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-135', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '策討丹楊七縣，使輔西屯歷陽以拒袁術，并招誘餘民，鳩合遺散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-136', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '袁術深怨策，乃陰遣間使齎印綬與丹楊宗帥陵陽祖郎等，使激動山越，大合衆，圖共攻策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-054-137', 'p0109', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '頃之，袁術遣從弟胤代尚為太守，而瑜與尚俱還壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-054-138', 'p0109', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '袁術聞其名，就署東城長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-055-139', 'p0109', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫策之襲袁術，欽隨從給事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-056-140', 'p0109', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '會堅薨，治扶翼策，依就袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-056-141', 'p0109', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '九州春秋曰：初平三年，揚州刺史陳禕死，袁術使瑀領揚州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-056-142', 'p0109', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '呂子衡忠篤亮直，性雖好奢，然以憂公為先，不足為損，避袁術自歸於兄，兄作大將，別領部曲，故憂兄事，乞為都督，辦護脩整，加之恪勤，與吳漢相類，故方之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-057-143', 'p0109', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '績年六歲，於九江見袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-057-144', 'p0109', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '父俊，官至陳相，為袁術所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-057-145', 'p0109', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '值袁術僭號，兄弟忿爭，天下鼎沸，羣賊並起，陳與比界，姧慝四布，俊厲威武，保疆境，賊不敢犯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-058-146', 'p0109', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '袁術與康有隙，將攻康，康遣遜及親戚還吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a05-036-full-147', 'p0109', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '宜官後爲袁術將，今鉅鹿宋子有耿球碑，是術所立，其書甚工，云是宜官也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-070-0', 'p0110', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '審配、逢紀盡忠之臣任其事，配字正南，魏郡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-070-1', 'p0110', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」彧曰：「紹兵雖多而法不整，田豐剛而犯上，許攸貪而不正，審配專而無謀，逢紀果而自用，顏良、文醜匹夫之勇，可一戰而擒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-2', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '魏郡審配，鉅鹿田豐，先賢行狀曰：「配字正南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-3', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '於是簡精兵十萬，騎萬匹，欲出攻許，以審配、逢紀統軍事，田豐、荀諶及南陽許攸為謀主，顏良、文醜為將帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-4', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」郭圖、審配曰：「兵書之法，十圍五攻，敵則能戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-5', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會攸家犯法，審配收繫之，攸不得志，遂奔曹操，而說使襲取淳于瓊等，瓊等時宿在烏巢，烏巢，地名，在滑州酸棗城東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-6', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '官度之敗，審配二子為曹操所禽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-7', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '護軍逢紀與配不睦，英雄記曰：「審配任用，與紀不睦，辛評、郭圖皆比於譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-8', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」未及定嗣，逢紀、審配宿以驕侈為譚所病，辛評、郭圖皆比於譚而與配、紀有隙。');
